entries[54797] = { ["name"] = "Fliegender Frostteppich", ["text"] = "Wird beim Aufheben gebunden\nReittier\nBenötigt Stufe 70\nBenötigt Schneiderei (425)\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen fliegenden Frostteppich oder gibt ihn wieder frei. Die Nutzung benötigt eine Schneiderfertigkeit von 425. Dieser Teppich passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an." }
entries[54798] = { ["name"] = "Muster: Fliegender Frostteppich", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (425)\nBenutzen: Lehrt Euch, wie man einen fliegenden Frostteppich näht.\n\nFliegender Frostteppich\nWird beim Aufheben gebunden\nReittier\nBenötigt Stufe 70\nBenötigt Schneiderei (425)\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen fliegenden Frostteppich oder gibt ihn wieder frei. Die Nutzung benötigt eine Schneiderfertigkeit von 425. Dieser Teppich passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBenötigt Mondgespinst , Zaubertuch , Schwarztuch , Gefrorene Kugel (4)" }
