entries[55054] = { ["name"] = "Gürtelschnalle aus Schwarzstahl", ["text"] = "Benötigt Stufe 80\nBenutzen: Bringt dauerhaft eine Gürtelschnalle aus Schwarzstahl an einem Gürtel an und fügt ihm so einen Sockel hinzu.\n\nDurch das Anbringen der Gürtelschnalle wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände der Stufe 500 oder höher angewandt werden.\nVerkaufspreis:" }
entries[55055] = { ["name"] = "Elementiumschildstachel", ["text"] = "Benötigt Stufe 80\nBenutzen: Bringt einen Elementiumstachel an Eurem Schild an, der bei jedem Blocken 90 to 133 Schaden verursacht.\n\nDurch das Anbringen des Elementiumschildstachels wird der Gegenstand seelengebunden." }
entries[55056] = { ["name"] = "Pyriumschildstachel", ["text"] = "Wird beim Anlegen gebunden\nBenötigt Stufe 85\nBenutzen: Bringt einen Pyriumstachel an Eurem Schild an, der beim Blocken manchmal 210 to 350 Schaden verursacht.\n\nDurch das Anbringen des Pyriumschildstachels wird der Gegenstand seelengebunden." }
entries[55057] = { ["name"] = "Pyriumwaffenkette", ["text"] = "Wird beim Anlegen gebunden\nBenötigt Stufe 81\nBenutzen: Bringt eine Kette an Eurer Waffe an, die die Wirkungsdauer von Entwaffnungseffekten um 60% verringert und Eure Trefferwertung um 40 erhöht. Ist nicht mit ähnlichen Effekten stapelbar.\n\nDas Anbringen der Waffenkette lässt die Waffe seelengebunden werden." }
